a=ad.read_h5ad(R/'02_pseudospots/counts.h5ad');check('DEV input obs only sample',list(a.obs.columns)==['sample']);check('DEVfullG0exactorder',key(a.var_names)==genehash);check('DEVcountsnonnegativeinteger',np.isfinite(a.X.data).all() and (a.X.data>=0).all() and np.equal(a.X.data,np.floor(a.X.data)).all());check('DEV count sums match',np.array_equal(np.asarray(a.X.sum(1)).ravel(),b.loc[a.obs_names,'post_G0_UMI']))
for name in ['DEV','DEV_OLD']+config()['sections']:
 o=outmap(name)
 if not (o/'RESULT_STATUS.json').exists():continue
 st=json.loads((o/'RESULT_STATUS.json').read_text());draw=np.load(o/'w_sf_draws.npy',mmap_mode='r');fp=json.loads((o/'run_fingerprint.json').read_text());labs=fp['labels'];kk='Epi_K32' if name=='DEV_OLD' else K;ll='Epi_other' if name=='DEV_OLD' else L;check(name+' draws shape',draw.shape==(st['actual_n_draws'],st['n_spots'],31));check(name+' finite nonnegative',np.isfinite(draw).all() and (draw>=0).all());derived=pd.read_csv(o/'posterior_derived.tsv.gz',sep='\t');e=draw[:,:,labs.index(kk)]+draw[:,:,labs.index(ll)];check(name+' draw epi quantile',np.allclose(np.quantile(e,.05,axis=0),derived.Epi_total_q05));ratio=np.divide(draw[:,:,labs.index(kk)],e,out=np.full_like(e,np.nan),where=e>=.1);bad=(e<.1).mean(0)>.05;ratio[:,bad]=np.nan;check(name+' draw ratio quantile',np.allclose(np.nanquantile(ratio,.05,axis=0),derived.I_state_q05,equal_nan=True));check(name+' stable min epochs',st['numerical_status']!='STABLE' or st['epochs']>=5000)
 inp=R/'02_pseudospots/counts.h5ad' if name.startswith('DEV') else o/'counts.h5ad';ai=ad.read_h5ad(inp,backed='r');sigpath=(S/'03_reference/MAIN' if name=='DEV_OLD' else R/'01_reference')/'signatures.tsv.gz'
 check(name+' current input hash',sha(inp)==fp['counts_sha256']);check(name+' frozen reference hash',sha(sigpath)==fp['signature_sha256']==st['reference_sha256']);check(name+' exact G0 order',key(ai.var_names)==genehash==fp['gene_hash']);check(name+' exact posterior spot order',list(derived.spot_id)==list(ai.obs_names));ai.file.close()
 for label,suffix in [('mean',None),('median',.5),('q95',.95)]:
  ep=e.mean(0) if suffix is None else np.quantile(e,suffix,axis=0);rr=np.nanmean(ratio,axis=0) if suffix is None else np.nanquantile(ratio,suffix,axis=0)
  check(name+' draw epi '+label,np.allclose(ep,derived['Epi_total_'+label]));check(name+' draw ratio '+label,np.allclose(rr,derived['I_state_'+label],equal_nan=True))
 check(name+' nearzero mask',np.array_equal(bad,derived.I_state_mean.isna()));hist=pd.read_csv(o/'training_history.tsv',sep='\t');check(name+' actual epoch history',len(hist)==st['epochs'])
 cv=pd.read_csv(o/'abundance_convergence.tsv',sep='\t');last=cv[cv.epoch.eq(cv.epoch.max())];check(name+' minimum formal checkpoint gap',(cv.epoch-cv.previous_epoch).ge(2000).all());check(name+' stable implies full criterion',st['numerical_status']!='STABLE' or (last.passed.all() and st['convergence']['loss_relative_change']<.005))
wt(pd.DataFrame(checks),R/'00_manifest/VALIDATION_CHECKS.tsv');js(R/'00_manifest/VALIDATION_STATUS.json',{'n_checks':len(checks),'n_failed':sum(not x['passed'] for x in checks),'time_epoch':time.time()});say('VALIDATION',len(checks),sum(not x['passed'] for x in checks));assert all(x['passed'] for x in checks)
